package com.example.rokidkeyboardbridge;
import org.json.*;
public class NavigationFreshnessTest{static int count;static void ok(boolean v){count++;if(!v)throw new AssertionError("freshness "+count);}public static void main(String[] args)throws Exception{long now=1000000;JSONObject j=NavigationFreshness.safe(new JSONObject().put("navigationActive",true).put("locationTime",now-12000).put("routeReady",true).put("routeTime",now-300000).put("latitude",35));ok(!j.has("latitude"));ok(NavigationFreshness.label(j,100,now,110).contains("12秒前"));ok(NavigationFreshness.label(j,100,now,110).contains("5分前"));ok(NavigationFreshness.label(j,100,now,15101).contains("通信更新待ち"));ok(!NavigationFreshness.linkFresh(100,99));ok(!NavigationFreshness.linkFresh(-1,100));ok(NavigationFreshness.linkFresh(0,15000));j.put("locationTime",now-90001);ok(NavigationFreshness.label(j,100,now,110).contains("位置更新待ち"));j.put("locationTime",now+1);ok(NavigationFreshness.label(j,100,now,110).contains("時刻不整合"));j.put("active",false);ok(NavigationFreshness.label(j,100,now,110).isEmpty());ok(NavigationFreshness.age(0,now).equals("未取得"));System.out.println("PASS navigation freshness "+count);}}
